sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float4 screen;
uniform shader blurred;
uniform float blur;
uniform float angle;
uniform float depth;
uniform float intensity;
layout(color) uniform half4 highlight;
layout(color) uniform half4 shadow;
uniform float angle_d;
uniform float angle_s;
layout(color) uniform half4 color_d;
layout(color) uniform half4 color_s;
uniform float intensity_d;
uniform float intensity_s;
uniform float elevation_d;
uniform float elevation_s;
uniform float spec;
uniform float style;
half4 classic(float2 coord, half4 src) {
    float s = max(blur * 0.2, 1.0);
    float dx = float(blurred.eval(coord + float2(s, 0.0)).a - blurred.eval(coord - float2(s, 0.0)).a);
    float dy = float(blurred.eval(coord + float2(0.0, s)).a - blurred.eval(coord - float2(0.0, s)).a);
    float3 n = normalize(float3(-dx * depth * 4.0, -dy * depth * 4.0, 1.0));
    float a = radians(angle);
    float3 l = normalize(float3(cos(a), -sin(a), 0.8));
    float lit = dot(n, l) - l.z;
    float3 base = float3(src.rgb) / float(src.a);
    float k = clamp(intensity, 0.0, 1.0);
    float3 rgb = lit > 0.0 ? mix(base, float3(highlight.rgb), clamp(lit * 2.0, 0.0, 1.0) * k * float(highlight.a))
                           : mix(base, float3(shadow.rgb), clamp(-lit * 2.0, 0.0, 1.0) * k * float(shadow.a));
    return half4(half3(rgb) * src.a, src.a);
}
half4 standard(float2 coord, half4 src) {
    float2 hi = max(size - 0.5, float2(0.5));
    float2 at = clamp(coord, float2(0.5), hi);
    float2 lo = screen.xy;
    float2 up = screen.xy + screen.zw;
    float4 solid = float4(step(-1.5, lo.x) * step(0.5, image.eval(float2(clamp(lo.x, 0.5, hi.x), at.y)).a),
                          step(up.x, size.x + 1.5) * step(0.5, image.eval(float2(clamp(up.x, 0.5, hi.x), at.y)).a),
                          step(-1.5, lo.y) * step(0.5, image.eval(float2(at.x, clamp(lo.y, 0.5, hi.y))).a),
                          step(up.y, size.y + 1.5) * step(0.5, image.eval(float2(at.x, clamp(up.y, 0.5, hi.y))).a));
    float2 m = float2(min(blur, 0.5 * min(size.x, size.y)));
    float2 cmin = mix(float2(-1e4), m, solid.xz);
    float2 cmax = mix(float2(1e4), size - m, solid.yw);
    float k = max(floor(blur * 0.1), 1.0);
    float dx = float(blurred.eval(clamp(coord + float2(k, 0.0), cmin, cmax)).a - blurred.eval(clamp(coord - float2(k, 0.0), cmin, cmax)).a) / k;
    float dy = float(blurred.eval(clamp(coord + float2(0.0, k), cmin, cmax)).a - blurred.eval(clamp(coord - float2(0.0, k), cmin, cmax)).a) / k;
    float slope = 0.418 * blur;
    float3 n = normalize(float3(-dx * slope, -dy * slope, 1.0));
    float3 ld = normalize(float3(cos(radians(angle_d)), -sin(radians(angle_d)), elevation_d));
    float3 ls = normalize(float3(cos(radians(angle_s)), -sin(radians(angle_s)), elevation_s));
    float dotS = dot(n, ls);
    if (dotS < -0.004) return half4(0.0, 0.0, 0.0, src.a);
    float3 base = float3(src.rgb) / float(src.a);
    float d = clamp(intensity_d, 0.0, 1.0) * dot(n, ld);
    float3 rgb = clamp(base + (float3(color_d.rgb) - base) * d * float(color_d.a), 0.0, 1.0);
    float sp = clamp(intensity_s, 0.0, 1.0) * (dotS > 0.0001 ? pow(dotS, max(spec, 0.001)) : 0.0);
    rgb = mix(rgb, float3(color_s.rgb), clamp(sp, 0.0, 1.0) * float(color_s.a));
    return half4(half3(rgb) * src.a, src.a);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0 || blur <= 0.0) return src;
    return style < 0.5 ? classic(coord, src) : standard(coord, src);
}
